const OIDC_TRANSACTION_KEY="coifesp_oidc_transaction";const OIDC_TRANSACTION_MAX_AGE_MS=10*60*1000;
function saveOidcTransaction(nonce,verifier){sessionStorage.setItem("pkce_verifier",verifier);sessionStorage.setItem("oidc_state",nonce);try{localStorage.setItem(OIDC_TRANSACTION_KEY,JSON.stringify({state:nonce,verifier,created_at:Date.now()}))}catch(e){}}
