async function login(){const verifier=b64(crypto.getRandomValues(new Uint8Array(32)));const nonce=b64(crypto.getRandomValues(new Uint8Array(18)));saveOidcTransaction(nonce,verifier);const challenge=await sha256(verifier);const u=new URL(`${state.config.issuer}/protocol/openid-connect/auth`);u.search=new URLSearchParams({client_id:state.config.client_id,response_type:"code",scope:"openid",redirect_uri:state.config.redirect_uri,code_challenge:challenge,code_challenge_method:"S256",state:nonce,prompt:"login"});location.assign(u)}
