function renderTeamProjects(){const notices=Object.fromEntries(state.projectNotifications.map(x=>[x.project_id,x])),total=state.projectNotifications.reduce((n,x)=>n+x.unread_count,0),badge=$('#project-unread-count');badge.textContent=total;badge.classList.toggle('hidden',!total);const listEl=$('#team-project-list');if(listEl)listEl.innerHTML=state.teamProjects.map(p=>{const unread=notices[p.project_id]?.unread_count||0;return `<article class="card"><div class="card-head"><div><h3>${esc(p.name)} ${unread?`<span class="badge">${unread}</span>`:''}</h3><div class="meta"><span>${esc(p.project_id)}</span><span>发起团队 ${esc(p.owner_team_id)}</span></div></div><button class="secondary" data-open-team-project="${esc(p.project_id)}">打开</button></div><p class="muted">${esc(p.description)}</p></article>`}).join('')||empty('尚无团队项目');$$('[data-open-team-project]').forEach(x=>x.onclick=()=>openTeamProject(x.dataset.openTeamProject))}
