function teamTaskCard(t){const me=state.account.team_id,target=t.target_team_id===me,source=t.source_team_id===me;let actions='';if(target&&t.status==='proposed')actions=`<button class="secondary" data-team-task-action="reject" data-team-task="${esc(t.task_id)}">拒绝</button><button class="primary" data-team-task-action="accept" data-team-task="${esc(t.task_id)}">接受</button>`;if(target&&['accepted','changes_requested'].includes(t.status))actions=`<button class="secondary" data-team-task-action="assign" data-team-task="${esc(t.task_id)}">内部指派</button>${t.assigned_account_id?`<button class="primary" data-team-task-action="start" data-team-task="${esc(t.task_id)}">开始执行</button>`:''}`;if(target&&t.status==='in_progress')actions=`<button class="primary" data-team-task-action="submit" data-team-task="${esc(t.task_id)}">提交项目资料</button>`;if(source&&t.status==='submitted')actions=`<button class="secondary" data-team-task-action="changes" data-team-task="${esc(t.task_id)}">要求修改</button><button class="primary" data-team-task-action="verify" data-team-task="${esc(t.task_id)}">验收通过</button>`;if((target||source)&&!['verified','rejected'].includes(t.status))actions+=`<button class="secondary" data-team-task-action="schedule" data-team-task="${esc(t.task_id)}">调整期限</button>`;return `<article class="card"><h4>${esc(t.title)}</h4><div class="meta"><span>${esc(t.source_team_id)} → ${esc(t.target_team_id)}</span><span class="pill ${t.status==='submitted'?'orange':'green'}">${stateName(t.status)}</span><span class="pill ${t.priority==='urgent'?'orange':'green'}">${esc(PRIORITY_LABELS[t.priority]||t.priority)}</span>${t.assigned_account_id?`<span>内部负责人 ${esc(t.assigned_account_id)}</span>`:''}</div><p>${esc(t.description)}</p><p class="muted">验收标准：${esc(t.acceptance_criteria)}</p><div class="meta">${formatDue(t)}</div><div class="task-actions">${actions}</div></article>`}
const renderTeamProjectBase=renderTeamProject;renderTeamProject=function(){renderTeamProjectBase();const p=state.teamProject.project,owner=p.owner_team_id===state.account.team_id;const topics=state.projectTopics.map(x=>{const contributions=state.topicContributions[x.topic_id]||[];return `<article class="card"><div class="card-head"><div><h4>${esc(x.title)}</h4><div class="meta"><span>${esc(x.proposed_by_team_id)}</span><span class="pill ${x.status==='open'?'orange':'green'}">${x.status==='open'?'讨论中':'已决议'}</span>${x.origin==='agent_confirmed'?`<span>Agent 建议 · ${esc(x.source_agent_run_id)}</span>`:'<span>人工议题</span>'}</div></div></div><p>${esc(x.context)}</p>${contributions.map(c=>`<div class="card"><strong>${esc(c.team_id)}</strong><p>${esc(c.content)}</p></div>`).join('')}${x.decision?`<div class="credential-box"><strong>项目决议</strong><p>${esc(x.decision)}</p></div>`:''}${x.status==='open'?`<div class="task-actions"><button class="secondary" data-topic-contribute="${esc(x.topic_id)}">团队发言</button>${owner?`<button class="primary" data-topic-decide="${esc(x.topic_id)}">确认决议</button>`:''}</div>`:''}</article>`}).join('')||empty('尚无计划议题');const drafts=state.collaborationDrafts.map(collaborationDraftCard).join('')||empty('尚无 Agent 协作草案');$('#team-project-detail').insertAdjacentHTML('beforeend',`<section><div class="panel-head"><h3>Agent 协作草案</h3><button class="primary" data-import-agent-drafts>从已完成 Agent 导入</button></div><p class="muted">Agent 只能起草消息、团队任务和计划议题。编辑并确认后才会代表本团队执行。</p>${drafts}</section><section><div class="panel-head"><h3>计划协商与决议</h3><div class="task-actions"><button class="secondary" data-new-project-topic>提出议题</button><button class="primary" data-agent-topic>确认 Agent 建议为议题</button></div></div>${topics}</section>`);$('[data-import-agent-drafts]').onclick=importAgentDrafts;$('[data-new-project-topic]').onclick=()=>newProjectTopic(false);$('[data-agent-topic]').onclick=()=>newProjectTopic(true);$$('[data-draft-action]').forEach(x=>x.onclick=()=>collaborationDraftAction(x));$$('[data-topic-contribute]').forEach(x=>x.onclick=()=>form('团队参与议题讨论',[{name:'content',label:'本团队意见',type:'textarea',required:true}],v=>projectCollaborationCommand(`topics/${encodeURIComponent(x.dataset.topicContribute)}/contributions`,v)));$$('[data-topic-decide]').forEach(x=>x.onclick=()=>form('确认项目决议',[{name:'decision',label:'最终决议',type:'textarea',required:true}],v=>projectCollaborationCommand(`topics/${encodeURIComponent(x.dataset.topicDecide)}:decide`,v)))}
function collaborationDraftCard(x){const label={message:'团队消息',task:'团队任务',topic:'计划议题'}[x.kind]||x.kind,p=x.payload,summary=x.kind==='message'?`${p.target_team_id}：${p.content}`:x.kind==='task'?`${p.target_team_id} · ${p.title} · 验收：${p.acceptance_criteria}`:`${p.title}：${p.context}`;return `<article class="card"><div class="card-head"><div><h4>${esc(label)}</h4><div class="meta"><span class="pill ${x.status==='pending'?'orange':'green'}">${x.status==='pending'?'待确认':x.status==='executed'?'已执行':'已拒绝'}</span><span>来源 ${esc(x.source_agent_run_id)}</span><span>v${x.version}</span></div></div>${x.status==='pending'?`<div class="task-actions"><button class="secondary" data-draft-action="edit" data-draft="${esc(x.draft_id)}">编辑</button><button class="secondary" data-draft-action="reject" data-draft="${esc(x.draft_id)}">拒绝</button><button class="primary" data-draft-action="execute" data-draft="${esc(x.draft_id)}">确认执行</button></div>`:''}</div><p>${esc(summary)}</p>${x.executed_subject_id?`<div class="meta">已创建 ${esc(x.executed_subject_id)}</div>`:''}${x.rejection_reason?`<div class="meta">拒绝原因 ${esc(x.rejection_reason)}</div>`:''}</article>`}
const renderTeamProjectWithTopics=renderTeamProject;renderTeamProject=function(){renderTeamProjectWithTopics();const statuses=Object.fromEntries(state.runs.map(x=>[x.run_id,x])),labels={analysis:'分析规划',collaboration_actions:'协作草案',delivery_review:'交付评审'},history=state.projectAgentRuns.map(x=>{const run=statuses[x.run_id];return `<article class="card"><div class="card-head"><div><h4>${esc(x.run_id)}</h4><div class="meta"><span class="pill green">${esc(labels[x.mode]||x.mode)}</span><span>${esc(run?stateName(run.status):'已登记')}</span><span>${new Date(x.created_at).toLocaleString()}</span></div></div>${run?`<button class="secondary" data-project-run-open="${esc(x.run_id)}">查看运行</button>`:''}</div></article>`}).join('')||empty('尚未启动项目 Agent');$('#team-project-detail').insertAdjacentHTML('beforeend',`<section><div class="panel-head"><h3>项目 Agent 历史</h3></div>${history}</section>`);$$('[data-project-run-open]').forEach(x=>x.onclick=()=>{show('agents');openAgentWorkbench(x.dataset.projectRunOpen)});const me=state.account.team_id,proposalEntries=Object.entries(state.scheduleProposals||{}).flatMap(([taskId,proposals])=>proposals.filter(p=>p.status==='pending'||p.decided_by_team_id===me||p.proposed_by_team_id===me).map(p=>scheduleProposalCard(taskId,p)));const pendingCount=Object.values(state.scheduleProposals||{}).flat().filter(p=>p.status==='pending').length;$('#team-project-detail').insertAdjacentHTML('beforeend',`<section><div class="panel-head"><div><h3>任务期限变更</h3>${pendingCount?`<span class="badge">${pendingCount} 待确认</span>`:''}</div><p class="muted small">已接受任务的期限必须经对方团队确认后才会变更；活动流记录每次变更的团队、时间和原因。</p></div>${proposalEntries.join('')||empty('暂无期限变更提议')}</section>`);$$('[data-schedule-decide]').forEach(x=>x.onclick=()=>decideScheduleProposal(x.dataset.scheduleTask,x.dataset.scheduleProposal,x.dataset.scheduleDecide==='true'))}
function importAgentDrafts(){const completed=new Set(state.runs.filter(x=>x.status==='completed').map(x=>x.run_id)),runs=state.projectAgentRuns.filter(x=>x.mode==='collaboration_actions'&&completed.has(x.run_id));if(!runs.length)return toast('当前没有已完成的“协作草案”模式项目 Agent',true);form('导入 Agent 协作草案',[{name:'run_id',label:'已完成协作草案 Agent',type:'select',options:runs.map(x=>[x.run_id,x.run_id])}],async v=>{const id=state.teamProject.project.project_id;await api(`/v1/projects/${encodeURIComponent(id)}/agent-runs/${encodeURIComponent(v.run_id)}:import-drafts`,{method:'POST',body:'{}'});await openTeamProject(id,false);toast('Agent 协作草案已导入，请逐项审核')})}
function collaborationDraftAction(el){const draft=state.collaborationDrafts.find(x=>x.draft_id===el.dataset.draft);if(!draft)return;if(el.dataset.draftAction==='execute')return draftDecision(draft,'execute',{});if(el.dataset.draftAction==='reject')return form('拒绝 Agent 草案',[{name:'reason',label:'拒绝原因',type:'textarea',required:true}],v=>draftDecision(draft,'reject',v));const p=draft.payload,fields=draft.kind==='message'?[{name:'target_team_id',label:'目标团队',type:'select',options:projectTeamOptions()},{name:'content',label:'消息内容',type:'textarea',required:true,value:p.content}]:draft.kind==='task'?[{name:'target_team_id',label:'目标团队',type:'select',options:projectTeamOptions()},{name:'title',label:'任务标题',required:true,value:p.title},{name:'description',label:'任务说明',type:'textarea',required:true,value:p.description},{name:'acceptance_criteria',label:'验收标准',type:'textarea',required:true,value:p.acceptance_criteria}]:[{name:'title',label:'议题标题',required:true,value:p.title},{name:'context',label:'议题背景',type:'textarea',required:true,value:p.context}];form('编辑 Agent 协作草案',fields,v=>draftUpdate(draft,v))}
async function draftUpdate(draft,payload){const id=state.teamProject.project.project_id;await api(`/v1/projects/${encodeURIComponent(id)}/collaboration-drafts/${encodeURIComponent(draft.draft_id)}`,{method:'PUT',body:JSON.stringify({expected_version:draft.version,payload})});await openTeamProject(id,false);toast('草案已更新')}
async function draftDecision(draft,action,extra){const id=state.teamProject.project.project_id;await api(`/v1/projects/${encodeURIComponent(id)}/collaboration-drafts/${encodeURIComponent(draft.draft_id)}:${action}`,{method:'POST',body:JSON.stringify({expected_version:draft.version,reason:extra.reason||''})});await openTeamProject(id,false);toast(action==='execute'?'草案已确认执行':'草案已拒绝')}
function newProjectTopic(fromAgent){const runs=state.runs.filter(x=>x.owner_principal_id===state.identity.principal_id||!x.owner_principal_id);if(fromAgent&&!runs.length)return toast('请先运行项目协作 Agent，再将其建议确认为议题',true);const fields=[{name:'title',label:fromAgent?'Agent 建议标题':'议题标题',required:true},{name:'context',label:fromAgent?'经人工检查后确认的 Agent 建议':'议题背景与待讨论方案',type:'textarea',required:true}];if(fromAgent)fields.unshift({name:'source_agent_run_id',label:'来源 Agent 运行',type:'select',options:runs.map(x=>[x.run_id,`${x.run_id} · ${stateName(x.status)}`])});form(fromAgent?'确认 Agent 建议为项目议题':'提出项目议题',fields,v=>projectCollaborationCommand('topics',v))}
function projectTeamOptions(){return state.teamProject.teams.filter(x=>x.team_id!==state.account.team_id).map(x=>[x.team_id,`${x.name} · ${x.team_id}`])}
function sendProjectMessage(){form('发送团队消息',[{name:'target_team_id',label:'接收团队',type:'select',options:projectTeamOptions()},{name:'content',label:'消息内容',type:'textarea',required:true}],v=>projectCollaborationCommand('messages',v))}
function createTeamTask(){form('布置团队任务',[{name:'target_team_id',label:'目标团队',type:'select',options:projectTeamOptions()},{name:'title',label:'任务标题',required:true},{name:'description',label:'任务说明',type:'textarea'},{name:'acceptance_criteria',label:'验收标准',type:'textarea',required:true},{name:'priority',label:'优先级',type:'select',options:[['low','低'],['normal','普通'],['high','高'],['urgent','紧急']]},{name:'due_at',label:'截止时间（浏览器本地时区，提交后换算为 UTC）',type:'datetime-local'}],async v=>{const due=v.due_at?new Date(v.due_at):null;if(due&&isNaN(due.getTime()))return toast('截止时间无效',true);if(due&&due.getTime()<=Date.now())return toast('截止时间必须晚于当前时间',true);await projectCollaborationCommand('tasks',{...v,due_at:due?due.toISOString():null});toast(`任务已创建${due?`，截止时间（UTC）：${due.toISOString()}`:''}`)})}
function changeTaskSchedule(taskId){const task=state.teamTasks.find(x=>x.task_id===taskId);if(!task)return toast('任务已刷新，请重新打开',true);const dueLocal=task.due_at?new Date(new Date(task.due_at).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';form('调整任务期限',[{name:'priority',label:'优先级',type:'select',options:[['low','低'],['normal','普通'],['high','高'],['urgent','紧急']],value:task.priority},{name:'due_at',label:'新截止时间（留空保持不变）',type:'datetime-local',value:dueLocal},{name:'clear_due_at',label:'清除截止时间',type:'select',options:[['false','否'],['true','是清除截止时间']]},{name:'reason',label:'变更原因（缩短期限时必填）',type:'textarea'}],async v=>{const due=v.due_at?new Date(v.due_at):null;if(due&&isNaN(due.getTime()))return toast('截止时间无效',true);if(due&&due.getTime()<=Date.now())return toast('截止时间必须晚于当前时间',true);const body={priority:v.priority,due_at:due?due.toISOString():null,clear_due_at:v.clear_due_at==='true',expected_schedule_version:task.schedule_version,reason:v.reason||''};if(body.clear_due_at&&body.due_at)return toast('不能同时清除并设置截止时间',true);const id=state.teamProject.project.project_id;const result=await api(`/v1/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(taskId)}/schedule`,{method:'PATCH',body:JSON.stringify(body)});await openTeamProject(id,false);if(result.result==='updated')toast('期限已直接更新（任务尚未被对方接受）');else toast('已创建期限变更提议，等待对方团队确认')})}
async function decideScheduleProposal(taskId,proposalId,accept){form(accept?'接受期限变更':'拒绝期限变更',[{name:'reason',label:accept?'接受说明（可选）':'拒绝原因',type:'textarea'}],async v=>{const id=state.teamProject.project.project_id;const proposal=(state.scheduleProposals[taskId]||[]).find(x=>x.proposal_id===proposalId);if(!proposal)return toast('提议已刷新，请重新打开',true);await api(`/v1/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(taskId)}/schedule-proposals/${encodeURIComponent(proposalId)}:decide`,{method:'POST',body:JSON.stringify({accept,reason:v.reason||'',expected_proposal_version:proposal.version})});await openTeamProject(id,false);toast(accept?'期限变更已接受并生效':'期限变更已拒绝，原期限保持不变')})}
function scheduleProposalCard(taskId,p){const me=state.account.team_id,decider=p.proposed_by_team_id!==me,statuses={pending:'待确认',accepted:'已接受',rejected:'已拒绝',superseded:'已替代'};const fmt=d=>d?new Date(d).toLocaleString():'无';return `<article class="card"><div class="card-head"><div><h4>期限变更提议</h4><div class="meta"><span class="pill ${p.status==='pending'?'orange':'green'}">${esc(statuses[p.status]||p.status)}</span><span>提出团队 ${esc(p.proposed_by_team_id)}</span><span>优先级 ${esc(PRIORITY_LABELS[p.old_priority]||p.old_priority)} → ${esc(PRIORITY_LABELS[p.new_priority]||p.new_priority)}</span><span>截止 ${esc(fmt(p.old_due_at))} → ${esc(fmt(p.new_due_at))}</span></div></div>${p.status==='pending'&&decider?`<div class="task-actions"><button class="secondary" data-schedule-decide="false" data-schedule-task="${esc(taskId)}" data-schedule-proposal="${esc(p.proposal_id)}">拒绝</button><button class="primary" data-schedule-decide="true" data-schedule-task="${esc(taskId)}" data-schedule-proposal="${esc(p.proposal_id)}">接受</button></div>`:''}</div><p>${esc(p.reason||'（未填写原因）')}</p>${p.decision_reason?`<p class="muted">决定说明：${esc(p.decision_reason)}</p>`:''}</article>`}
async function projectCollaborationCommand(path,body){const id=state.teamProject.project.project_id;await api(`/v1/projects/${encodeURIComponent(id)}/${path}`,{method:'POST',body:JSON.stringify(body)});await openTeamProject(id,false);toast('项目协作已更新')}
async function teamTaskAction(el){const id=state.teamProject.project.project_id,task=el.dataset.teamTask,base=`/v1/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(task)}`,action=el.dataset.teamTaskAction;if(action==='accept'||action==='reject')return projectCollaborationCommand(`tasks/${encodeURIComponent(task)}:respond`,{accept:action==='accept'});if(action==='start')return projectCollaborationCommand(`tasks/${encodeURIComponent(task)}:start`,{});if(action==='schedule')return changeTaskSchedule(task);if(action==='assign')return form('团队内部指派',[{name:'account_id',label:'内部负责人',type:'select',options:state.teamAccounts.map(x=>[x.account_id,`${x.display_name} · ${x.username}`])}],v=>projectCollaborationCommand(`tasks/${encodeURIComponent(task)}:assign`,v));if(action==='verify'||action==='changes')return form(action==='verify'?'验收任务':'要求修改',[{name:'note',label:'验收意见',type:'textarea',required:true}],v=>projectCollaborationCommand(`tasks/${encodeURIComponent(task)}:review`,{accept:action==='verify',note:v.note}));if(action==='submit'){const own=state.projectResources.filter(x=>x.owner_team_id===state.account.team_id&&x.propagation!=='team_private');const dialog=$('#modal');$('#modal-title').textContent='提交团队任务';$('#modal-fields').innerHTML=`<div class="artifact-picker">${own.map(x=>`<label class="card"><input type="checkbox" name="resource" value="${esc(x.resource_id)}"><strong>${esc(x.title)}</strong></label>`).join('')||empty('请先关联一份项目可见资料')}</div>`;dialog.showModal();$('#modal-form').onsubmit=async e=>{e.preventDefault();const resource_ids=new FormData(e.target).getAll('resource');if(!resource_ids.length)return toast('至少选择一份资料',true);try{await projectCollaborationCommand(`tasks/${encodeURIComponent(task)}:submit`,{resource_ids});dialog.close()}catch(err){toast(err.message,true)}}}}
function addProjectTeam(){const options=state.relations.map(x=>[x.team.team_id,`${x.team.name} · ${x.team.handle}`]);form('邀请关联团队',[{name:'team_id',label:'团队',type:'select',options},{name:'assignment_name',label:'项目职责名称',required:true},{name:'kind',label:'职责类型',type:'select',options:[['product','产品'],['engineering','工程'],['quality','质量'],['design','设计'],['operations','运维'],['custom','自定义']]}],async v=>{await api(`/v1/projects/${state.teamProject.project.project_id}/teams`,{method:'POST',body:JSON.stringify(v)});await openTeamProject(state.teamProject.project.project_id,false)})}
function bindProjectResource(){const options=state.artifacts.filter(x=>x.owner_tenant_id===state.account.team_id).map(x=>[x.artifact_id,`${x.artifact_id} · ${x.media_type}`]);form('关联团队交付物到项目',[{name:'artifact_id',label:'交付物',type:'select',options},{name:'title',label:'项目资料标题',required:true},{name:'propagation',label:'传播等级',type:'select',options:[['team_private','团队私有'],['project_readonly','项目内只读'],['portable','可保存传播']]}],async v=>{const artifact=state.artifacts.find(x=>x.artifact_id===v.artifact_id&&x.owner_tenant_id===state.account.team_id);await api(`/v1/projects/${state.teamProject.project.project_id}/resources`,{method:'POST',body:JSON.stringify({...v,artifact_sha256:artifact.sha256})});await openTeamProject(state.teamProject.project.project_id,false)})}
function uploadProjectResource(){const dialog=$('#modal'),idempotencyKey=uid('project-resource');$('#modal-title').textContent='上传项目资料';$('#modal-fields').innerHTML=`<p class="muted">文件会进入不可变项目资料库。传播等级同时约束其他团队的预览、下载、收藏、转发和 Agent 使用。</p><label class="field">文件<input name="content" type="file" required></label><label class="field">资料标题<input name="title" required maxlength="256"></label><label class="field">传播等级<select name="propagation"><option value="team_private">团队私有 · 仅本团队</option><option value="project_readonly" selected>项目内只读 · 其他团队仅在本项目查看</option><option value="portable">可保存传播 · 项目团队可下载和再分享</option></select></label>`;const fileInput=$('#modal-fields [name=content]'),titleInput=$('#modal-fields [name=title]');fileInput.onchange=()=>{if(!titleInput.value&&fileInput.files[0])titleInput.value=fileInput.files[0].name};dialog.showModal();$('#modal-form').onsubmit=async e=>{e.preventDefault();const values=new FormData(e.target),project=state.teamProject.project.project_id,body=new FormData();body.set('title',values.get('title'));body.set('propagation',values.get('propagation'));body.set('content',values.get('content'));try{const r=await fetch(`/v1/projects/${encodeURIComponent(project)}/resources:upload`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`,'Idempotency-Key':idempotencyKey},body,cache:'no-store'});if(!r.ok){let p={};try{p=await r.json()}catch{}throw Error(p.detail||p.title||`上传失败 (${r.status})`)}dialog.close();await openTeamProject(project,false);toast('项目资料已上传并完成完整性校验')}catch(err){toast(err.message,true)}}}
async function previewProjectResource(id){try{const project=state.teamProject.project.project_id,resource=state.projectResources.find(x=>x.resource_id===id),r=await fetch(`/v1/projects/${encodeURIComponent(project)}/resources/${encodeURIComponent(id)}/preview`,{headers:{Authorization:`Bearer ${state.token}`},cache:'no-store'});if(!r.ok)throw Error('当前账户不能预览该项目资料');const blob=await r.blob(),type=(resource?.media_type||blob.type||'application/octet-stream').toLowerCase(),dialog=$('#resource-preview'),body=$('#resource-preview-body');closeProjectResourcePreview(false);$('#resource-preview-title').textContent=resource?.title||'项目资料预览';body.replaceChildren();if(type.startsWith('text/')||['application/json','application/xml','application/yaml','application/x-yaml','application/javascript'].includes(type)){const pre=document.createElement('pre'),text=await blob.text(),limit=200000;pre.textContent=text.slice(0,limit)+(text.length>limit?'\n\n[预览已截断，请按传播权限下载完整文件]':'');body.append(pre)}else if(['image/png','image/jpeg','image/gif','image/webp'].includes(type)){state.previewUrl=URL.createObjectURL(blob);const image=document.createElement('img');image.src=state.previewUrl;image.alt=resource?.title||'项目资料';body.append(image)}else if(type==='application/pdf'){state.previewUrl=URL.createObjectURL(blob);const frame=document.createElement('iframe');frame.src=state.previewUrl;frame.title=resource?.title||'PDF 项目资料';body.append(frame)}else{body.textContent='该文件类型不支持安全的网页预览；如果传播等级允许，可下载后使用本地应用打开。'}dialog.onclose=()=>closeProjectResourcePreview(false);dialog.showModal()}catch(e){toast(e.message,true)}}
function closeProjectResourcePreview(close=true){const dialog=$('#resource-preview');if(close&&dialog.open)dialog.close();if(state.previewUrl){URL.revokeObjectURL(state.previewUrl);state.previewUrl=null}$('#resource-preview-body').replaceChildren()}
async function downloadProjectResource(id){try{const project=state.teamProject.project.project_id;const r=await fetch(`/v1/projects/${encodeURIComponent(project)}/resources/${encodeURIComponent(id)}/content`,{headers:{Authorization:`Bearer ${state.token}`}});if(!r.ok)throw Error('该传播等级不允许下载');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=id;a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message,true)}}
