function inboxActionCard(item){const task=item.task,labels={respond:'响应任务',assign:'安排内部负责人',start:'开始执行',submit:'提交交付',review:'验收交付'};return `<article class="card"><div class="card-head"><div><h4>${esc(task.title)}</h4><div class="meta"><span class="pill orange">${esc(labels[item.action]||item.action)}</span><span class="pill ${task.priority==='urgent'?'orange':'green'}">${esc(PRIORITY_LABELS[task.priority]||task.priority)}</span>${task.is_overdue?'<span class="pill orange">已逾期</span>':task.is_due_soon?'<span class="pill orange">临期</span>':''}${task.assigned_to_me?'<span class="pill green">分配给我</span>':''}<span>${esc(item.project_name)}</span><span>${esc(task.source_team_id)} → ${esc(task.target_team_id)}</span></div></div><button class="secondary" data-open-inbox-project="${esc(item.project_id)}">进入项目</button></div><p class="muted">${esc(task.acceptance_criteria)}</p><div class="meta">${formatDue(task)}</div></article>`}
