function renderCollaborationInbox(){const inbox=state.collaborationInbox,badge=$('#inbox-action-count');badge.textContent=inbox.action_count;badge.classList.toggle('hidden',!inbox.action_count);$('#collaboration-action-list').innerHTML=inbox.actions.map(inboxActionCard).join('')||empty(state.inboxFilter==='overdue'?'当前没有逾期任务':state.inboxFilter==='due_soon'?'当前没有 48 小时内到期的任务':state.inboxFilter==='mine'?'当前没有分配给当前账户的任务':'当前没有需要本团队处理的跨项目事项');$('#collaboration-activity-list').innerHTML=inbox.unread_activities.map(inboxActivityCard).join('')||empty('没有未读项目动态');$('#inbox-agent-run-list').innerHTML=state.inboxAgentRuns.map(x=>{const run=state.runs.find(r=>r.run_id===x.run_id),label=x.mode==='prioritization'?'优先级梳理':'状态简报';return `<article class="card"><div class="card-head"><div><h3>${esc(label)}</h3><div class="meta"><span class="pill ${run?.status==='failed'?'orange':'green'}">${esc(stateName(run?.status||'queued'))}</span><span>${esc(new Date(x.created_at).toLocaleString())}</span></div></div><button class="secondary" data-inbox-agent-run="${esc(x.run_id)}">打开会话</button></div></article>`}).join('')||empty('尚未运行收件箱 Agent');$$('[data-inbox-agent-run]').forEach(x=>x.onclick=()=>{show('agents');openAgentWorkbench(x.dataset.inboxAgentRun)});bindInboxProjects()}
async function refreshCollaborationInbox(){if(!state.config.product_workspace_enabled)return;const filter=state.inboxFilter,params=new URLSearchParams();if(filter==='overdue')params.set('overdue_only','true');if(filter==='due_soon')params.set('due_within_hours','48');if(filter==='mine')params.set('assigned_only','true');try{state.collaborationInbox=await api(`/v1/collaboration-inbox?${params}`);renderCollaborationInbox();renderOverview()}catch(e){toast(e.message,true)}}
