async function loadNotifications(append=false){if(!state.config.product_workspace_enabled)return;const params=new URLSearchParams();if(state.notificationTab==='unread')params.set('unread_only','true');if(state.notificationTab==='archived')params.set('archived_only','true');if(state.notificationCategory)params.set('category',state.notificationCategory);if(state.notificationProject)params.set('project_id',state.notificationProject);if(append&&state.notifications.next_cursor)params.set('cursor',state.notifications.next_cursor);try{const page=await api(`/v1/notifications?${params}`);state.notifications=append?{items:[...state.notifications.items,...page.items],unread_count:page.unread_count,next_cursor:page.next_cursor}:{...page};renderNotifications()}catch(e){toast(e.message,true)}}
function renderNotificationProjectOptions(){const select=$('#notification-project');if(!select)return;const current=state.notificationProject,options=[['','全部项目'],...state.teamProjects.map(p=>[p.project_id,`${p.name} · ${p.project_id}`])];select.innerHTML=options.map(([value,label])=>`<option value="${esc(value)}"${value===current?' selected':''}>${esc(label)}</option>`).join('');if(!options.some(([value])=>value===current)){state.notificationProject='';select.value=''}}
function openNotificationProject(projectId){if(!state.teamProjects.some(p=>p.project_id===projectId))return toast('该通知对应的业务对象所在项目已不可用或当前账户无权访问',true);openTeamProject(projectId)}
function notificationCard(item){const categoryLabels={task:'任务',message:'消息',resource:'资料',topic:'议题',agent:'Agent',due_soon:'临期提醒',overdue:'逾期提醒'},audienceLabel=item.activity_sequence===0?'团队定向':'项目广播';const actions=[];if(!item.read_at)actions.push(`<button class="secondary" data-notification-action="mark-read" data-notification="${esc(item.notification_id)}">标记已读</button>`);if(!item.archived_at)actions.push(`<button class="secondary" data-notification-action="archive" data-notification="${esc(item.notification_id)}">归档</button>`);else actions.push(`<button class="secondary" data-notification-action="restore" data-notification="${esc(item.notification_id)}">恢复</button>`);return `<article class="card"><div class="card-head"><div><h4>${esc(item.title)}</h4><div class="meta"><span class="pill ${item.category==='overdue'?'orange':'green'}">${esc(categoryLabels[item.category]||item.category)}</span><span class="pill">${audienceLabel}</span>${item.read_at?'':'<span class="pill orange">未读</span>'}${item.archived_at?'<span class="pill">已归档</span>':''}<span>${esc(new Date(item.created_at).toLocaleString())}</span></div></div><div class="task-actions"><button class="secondary" data-notification-open-project="${esc(item.project_id)}">查看项目</button>${actions.join('')}</div></div><p>${esc(item.summary)}</p></article>`}
function renderNotifications(){$('#notification-list').innerHTML=state.notifications.items.map(notificationCard).join('')||empty(state.notificationTab==='archived'?'没有已归档的通知':state.notificationTab==='unread'?'没有未读通知':'还没有通知');$('#notification-more').classList.toggle('hidden',!state.notifications.next_cursor);renderNotificationProjectOptions();$$('[data-notification-action]').forEach(x=>x.onclick=()=>notificationAction(x.dataset.notification,x.dataset.notificationAction));$$('[data-notification-open-project]').forEach(x=>x.onclick=()=>openNotificationProject(x.dataset.notificationOpenProject));renderNotificationBadge()}
async function notificationAction(id,action){try{const item=await api(`/v1/notifications/${encodeURIComponent(id)}:${action}`,{method:'POST'});const index=state.notifications.items.findIndex(x=>x.notification_id===id);if(index>=0)state.notifications.items[index]=item;renderNotifications();refresh().catch(()=>{})}catch(e){toast(e.message,true)}}
