function empty(text){return `<div class="empty">${esc(text)}</div>`}
function taskCard(t,programId=t.program_id||state.program?.program_id){return `<article class="card"><div class="card-head"><div><h4>${esc(t.title)}</h4><div class="meta"><span class="pill ${t.state==='submitted'?'orange':'green'}">${stateName(t.state)}</span><span>负责人 ${esc(t.assignee_id)}</span></div></div></div><p class="muted">${esc(t.description)}</p><div class="task-actions">${t.state==='proposed'?`<button class="primary" data-task-action="respond" data-program="${esc(programId)}" data-task="${esc(t.assignment_id)}">接受</button>`:''}${t.state==='accepted'?`<button class="primary" data-task-action="start" data-program="${esc(programId)}" data-task="${esc(t.assignment_id)}">开始</button>`:''}${t.state==='in_progress'?`<button class="primary" data-task-action="submit" data-program="${esc(programId)}" data-task="${esc(t.assignment_id)}">提交交付物</button>`:''}${t.state==='submitted'?`<button class="primary" data-task-action="review" data-program="${esc(programId)}" data-task="${esc(t.assignment_id)}">验收</button>`:''}</div></article>`}
function renderTasks(){let items=state.tasks;if(state.taskFilter==='active')items=items.filter(x=>!["verified","rejected"].includes(x.state));$("#task-list").innerHTML=items.map(t=>taskCard(t,t.program_id)).join("")||empty("没有任务");bindTaskActions()}
