async function taskAction(action,programId,id){let task=state.tasks.find(x=>x.program_id===programId&&x.assignment_id===id);if(!task&&state.program?.program_id===programId)task=state.program.assignments.find(x=>x.assignment_id===id);if(!task)return toast("任务已刷新，请重新打开",true);if(!state.program||state.program.program_id!==programId)await openProgram(programId,false);const base=`/v1/governance/programs/${programId}/assignments/${id}`;if(action==='respond')return command(base+':respond',{accept:true,reason:"已接受任务"});if(action==='start')return command(base+':start',{});if(action==='submit')return chooseTaskArtifacts(base);if(action==='review')return form("验收任务",[{name:"note",label:"验收意见",type:"textarea",required:true},{name:"accept",label:"决定",type:"select",options:[["true","通过"],["false","要求修改"]]}],v=>command(base+':review',{accept:v.accept==='true',note:v.note}))}
const taskCardWithProgram=taskCard;taskCard=(task,programId)=>taskCardWithProgram(task,typeof programId==="string"?programId:undefined);
function renderRuns(){$("#agent-list").innerHTML=state.runs.map(r=>`<article class="card"><div class="card-head"><div><h3>${esc(r.run_id)}</h3><div class="meta"><span class="pill ${r.status==='failed'?'orange':'green'}">${stateName(r.status)}</span><span>${r.turns} 轮</span><span>${r.total_tokens} tokens</span></div></div><button class="secondary" data-run-open="${esc(r.run_id)}">打开会话</button></div></article>`).join("")||empty("还没有 Agent 运行");$$('[data-run-open]').forEach(x=>x.onclick=()=>openAgentWorkbench(x.dataset.runOpen))}
function renderConversation(messages){$("#conversation-list").innerHTML=messages.map(m=>`<div class="message ${esc(m.role)}"><small>${m.role==='user'?'你':'Agent'}</small>${esc(m.content)}</div>`).join("")||empty("Agent 尚未产生可见消息")}
function appendAgentEvent(type,data){const el=document.createElement("div");el.className="event";el.innerHTML=`<strong>${esc(type)}</strong><pre>${esc(data)}</pre>`;$("#event-list").append(el)}
function renderRunAuthorizations(auth){const host=$("#agent-workbench");let panel=$("#run-authorizations");if(!auth||!(auth.tools&&auth.tools.length||auth.skills&&auth.skills.length)){if(panel)panel.remove();return}const tools=auth.tools.map(t=>`<span class="pill green">${esc(TOOL_LABELS[t.tool_id]||t.tool_id)} · v${esc(t.version)}</span>`).join(" ")||'<span class="muted">本次运行未授权任何工具</span>';const skills=auth.skills.map(s=>`<span class="pill orange">${esc(s.name)} @ ${esc(s.version)}</span>`).join(" ")||'<span class="muted">未选择 Skill</span>';if(!panel){panel=document.createElement("div");panel.id="run-authorizations";panel.className="panel";host.prepend(panel)}panel.innerHTML=`<div class="panel-head"><div><p class="eyebrow">RUN AUTHORIZATION</p><h3>本次运行授权</h3></div></div><p class="small">工具：${tools}</p><p class="small">Skill：${skills}</p><p class="muted small">授权在运行创建时固定，创建后不能扩大；高风险工具每次调用仍需人工审批。</p>`}
async function openAgentWorkbench(id){closeAgentWorkbench();state.activeRun=state.runs.find(x=>x.run_id===id)||{run_id:id};$("#agent-workbench-title").textContent=id;$("#agent-workbench").classList.remove("hidden");$("#event-list").innerHTML="";try{const [conversation,authorizations]=await Promise.all([api(`/v1/agent-runs/${encodeURIComponent(id)}/conversation`),api(`/v1/agent-runs/${encodeURIComponent(id)}/authorizations`).catch(()=>null)]);renderRunAuthorizations(authorizations);state.activeRun={...state.activeRun,version:conversation.run_version};renderConversation(conversation.messages);streamAgentEvents(id)}catch(e){toast(e.message,true)}}
