async function streamAgentEvents(id){
  const controller=new AbortController();state.eventAbort=controller;const path="/v1/agent-runs/"+encodeURIComponent(id)+"/events";const openStream=()=>{const headers={Authorization:"Bearer "+state.token},cursor=state.eventCursors[id]||0;if(cursor)headers["Last-Event-ID"]=String(cursor);return fetch(path,{headers,cache:"no-store",signal:controller.signal})};
  try{let response=await openStream();if(response.status===401&&state.sessionCoordinator)response=await state.sessionCoordinator.onUnauthorized({method:"GET",idempotencyKey:null,replay:openStream});if(!response.ok)throw Error("无法读取运行事件");const reader=response.body.getReader(),decoder=new TextDecoder(),newline=String.fromCharCode(10),separator=newline+newline;let buffer="";while(true){const chunk=await reader.read();buffer+=decoder.decode(chunk.value||new Uint8Array(),{stream:!chunk.done});let boundary;while((boundary=buffer.indexOf(separator))>=0){const block=buffer.slice(0,boundary);buffer=buffer.slice(boundary+separator.length);let type=null,data=null,eventId=null;block.split(newline).forEach(line=>{if(line.startsWith("id: "))eventId=Number(line.slice(4));else if(line.startsWith("event: "))type=line.slice(7);else if(line.startsWith("data: "))data=line.slice(6)});const previous=state.eventCursors[id]||0,fresh=!Number.isSafeInteger(eventId)||eventId>previous;if(type&&data&&fresh)appendAgentEvent(type,data);if(Number.isSafeInteger(eventId)&&eventId>previous)state.eventCursors[id]=eventId}if(chunk.done)break}if(state.activeRun?.run_id===id){const conversation=await api("/v1/agent-runs/"+encodeURIComponent(id)+"/conversation");state.activeRun.version=conversation.run_version;renderConversation(conversation.messages)}}catch(error){if(error.name!=="AbortError")toast(error.message,true)}
}
async function sendAgentControl(event){event.preventDefault();const content=$("#agent-control-content").value.trim();if(!content||!state.activeRun)return;try{const result=await api(`/v1/agent-runs/${encodeURIComponent(state.activeRun.run_id)}/control-commands`,{method:"POST",body:JSON.stringify({command_id:uid("workspace-control"),command_type:$("#agent-control-type").value,content,expected_run_version:state.activeRun.version})});state.activeRun=result.run;$("#agent-control-content").value="";renderConversation([...(await api(`/v1/agent-runs/${encodeURIComponent(state.activeRun.run_id)}/conversation`)).messages,{role:"user",content}]);state.eventAbort?.abort();streamAgentEvents(state.activeRun.run_id);toast("指令已发送给 Agent")}catch(e){toast(e.message,true)}}
