async function uploadArtifact(){const dialog=$("#modal");$("#modal-title").textContent="上传交付物";$("#modal-fields").innerHTML=`<label class="field">文件<input name="content" type="file" required></label><label class="field">交付物 ID<input name="artifact_id" required pattern="[A-Za-z0-9][A-Za-z0-9._:-]*"></label><label class="field">类型<select name="kind"><option value="document">文档</option><option value="spreadsheet">表格</option><option value="presentation">演示文稿</option><option value="pdf">PDF</option><option value="source_code">源代码</option><option value="test_report">测试报告</option><option value="build">构建产物</option><option value="generic">其他</option></select></label><label class="field">信息分级<select name="classification"><option value="internal">内部</option><option value="confidential">机密</option><option value="restricted">受限</option><option value="public">公开</option></select></label><label class="field">隔离域（逗号分隔）<input name="compartments"></label><label class="field">可见团队（逗号分隔）<input name="visible_to_tenants" required value="${esc(state.identity.tenant_id)}"></label>`;dialog.showModal();$("#modal-form").onsubmit=async e=>{e.preventDefault();const fields=new FormData(e.target);const file=fields.get("content");const metadata={artifact_id:fields.get("artifact_id"),kind:fields.get("kind"),classification:fields.get("classification"),compartments:split(fields.get("compartments")),visible_to_tenants:split(fields.get("visible_to_tenants"))};const body=new FormData();body.set("metadata",JSON.stringify(metadata));body.set("content",file);try{const r=await fetch("/v1/artifacts:upload",{method:"POST",headers:{Authorization:`Bearer ${state.token}`,"Idempotency-Key":uid("artifact-upload")},body});if(!r.ok){let p={};try{p=await r.json()}catch{}throw Error(p.detail||p.title||`上传失败 (${r.status})`)}dialog.close();await refresh();show("artifacts");toast("交付物已上传并完成完整性校验")}catch(err){toast(err.message,true)}}}
