  const selectedEntries=state.agentRepositoryContext.map((item,index)=>({item,index})).filter(({item})=>!item.project_id||item.project_id===selectedProjectId),selected=selectedEntries.map(({item,index})=>"<article class=\"card\"><strong>"+esc(item.repository_id)+"</strong><span class=\"meta\">"+esc(item.commit.slice(0,12))+" · "+esc(item.paths.join(", "))+"</span><button type=\"button\" class=\"secondary\" data-code-unselect=\""+index+"\">移除</button></article>").join("")||empty("尚未选择代码文件"),repoHtml=repos.map(item=>"<article class=\"card\"><h4>"+esc(item.repository_id)+"</h4><div class=\"meta\"><span>"+esc(item.remote_repository_id)+"</span><span>"+esc(item.default_branch)+"</span></div><label class=\"field\">固定 commit（40 位 SHA）<input data-code-commit=\""+esc(item.repository_id)+"\" maxlength=\"40\"></label><label class=\"field\">文件路径<input data-code-path=\""+esc(item.repository_id)+"\" placeholder=\"src/module.py\"></label><button type=\"button\" class=\"secondary\" data-code-select=\""+esc(item.repository_id)+"\">读取预览并交给 Agent</button></article>").join("")||empty("尚未绑定仓库，请联系项目主导团队管理员"),draftHtml=drafts.map(item=>"<article class=\"card\"><h4>"+esc(item.draft_id)+"</h4><div class=\"meta\"><span class=\"pill "+(item.status==="pending"?"orange":"green")+"\">"+esc(item.status)+"</span><span>"+esc(item.base_commit.slice(0,12))+"</span></div><pre class=\"code-diff\">"+esc(item.patch_text)+"</pre>"+(item.status==="pending"?"<div class=\"task-actions\"><button type=\"button\" class=\"secondary\" data-code-approve=\""+esc(item.draft_id)+"\" data-version=\""+item.version+"\">确认应用</button><button type=\"button\" class=\"secondary\" data-code-reject=\""+esc(item.draft_id)+"\" data-version=\""+item.version+"\">拒绝</button></div>":"")+(item.patch_artifact_id?"<button type=\"button\" class=\"secondary\" data-artifact-download=\""+esc(state.account.team_id)+"\" data-artifact-id=\""+esc(item.patch_artifact_id)+"\" data-artifact-digest=\""+esc(item.patch_artifact_sha256)+"\">下载 Patch</button>":"")+"</article>").join("")||empty("暂无修改草案");
