async function openDocumentWorkspace(resourceId){
  const project=state.teamProject?.project;if(!project){toast("请先打开项目",true);return}if(!resourceId){const candidates=state.projectResources.filter(item=>item.media_type&&(item.media_type.includes("document")||item.media_type.includes("sheet")||item.media_type.includes("presentation")||item.media_type.includes("pdf"))),dialog=$("#modal");$("#modal-title").textContent="选择文档";$("#modal-fields").innerHTML=candidates.map(item=>"<button type=\"button\" class=\"card\" data-open-doc-resource=\""+esc(item.resource_id)+"\"><strong>"+esc(item.title)+"</strong><span class=\"meta\">"+esc(item.media_type)+"</span></button>").join("")||empty("项目中尚无可处理文档");dialog.showModal();$("#modal-form").onsubmit=event=>event.preventDefault();$$(`[data-open-doc-resource]`).forEach(button=>button.onclick=()=>openDocumentWorkspace(button.dataset.openDocResource));return}
  const base="/v1/projects/"+encodeURIComponent(project.project_id)+"/resources/"+encodeURIComponent(resourceId)+"/documents",resource=state.projectResources.find(item=>item.resource_id===resourceId);let versions=[],derivatives=[],drafts=[],contents=new Map();try{versions=await api(base+"/versions")}catch(e){toast(e.message,true)}try{derivatives=await api(base+"/derivatives")}catch(e){}try{drafts=await api(base+"/change-drafts")}catch(e){}for(const derivative of derivatives){if(derivative.status!=="ready")continue;try{contents.set(derivative.derivative_id,await api(base+"/derivatives/"+encodeURIComponent(derivative.derivative_id)+"/content"))}catch(e){}}
  const versionHtml=versions.map(item=>"<article class=\"card\"><div class=\"meta\"><span class=\"pill green\">v"+esc(item.version_number)+"</span><span>"+esc(item.reason)+"</span></div></article>").join("")||empty("尚无版本"),derivativeHtml=derivatives.map(item=>{const content=contents.get(item.derivative_id),selected=state.agentDocumentContext.find(entry=>entry.resource_id===resourceId&&entry.derivative_id===item.derivative_id),items=content&&Array.isArray(content.items)?content.items:[],fragments=items.map((fragment,index)=>"<label class=\"card\"><input type=\"checkbox\" data-doc-fragment=\""+esc(item.derivative_id)+"\" data-index=\""+index+"\" "+(selected&&selected.item_indexes.includes(index)?"checked":"")+"><strong>"+esc((fragment.location&&fragment.location.label)||((fragment.location&&fragment.location.kind)||"片段")+" #"+((fragment.location&&fragment.location.index)??index))+"</strong><span>"+esc(fragment.text)+"</span></label>").join("");return "<article class=\"card\"><div class=\"meta\"><span class=\"pill "+(item.status==="ready"?"green":"orange")+"\">"+esc(item.status)+"</span><span>"+esc(item.summary)+"</span></div>"+(fragments?"<div class=\"artifact-picker\">"+fragments+"</div>":"")+"</article>"}).join("")||empty("尚未解析"),draftHtml=drafts.map(item=>"<article class=\"card\"><div class=\"meta\"><span class=\"pill "+(item.status==="pending"?"orange":"green")+"\">"+esc(item.status)+"</span><span>v"+esc(item.version)+"</span></div><pre class=\"code-diff\">"+esc(item.modification_json)+"</pre>"+(item.status==="pending"?"<button type=\"button\" class=\"secondary\" data-doc-approve=\""+esc(item.draft_id)+"\" data-version=\""+item.version+"\">确认生成新版本</button><button type=\"button\" class=\"secondary\" data-doc-reject=\""+esc(item.draft_id)+"\" data-version=\""+item.version+"\">拒绝</button>":"")+"</article>").join("")||empty("暂无草案");
  const dialog=$("#modal");$("#modal-title").textContent="文档工作区："+(resource?resource.title:resourceId);$("#modal-fields").innerHTML="<p class=\"muted\">安全解析后可预览并只选择具体页、Sheet、Slide 或段落交给下一次项目 Agent。修改必须形成草案并人工确认，原版本始终保留。</p><button type=\"button\" class=\"secondary\" data-doc-parse>解析当前文档</button><h3>版本</h3>"+versionHtml+"<h3>解析预览与 Agent 片段选择</h3>"+derivativeHtml+"<h3>创建修改草案</h3><label class=\"field\">修改协议 JSON<textarea data-doc-modification></textarea></label><label class=\"field\">修改原因<input data-doc-reason></label><button type=\"button\" class=\"secondary\" data-doc-create-draft>创建草案</button><h3>修改草案与对照</h3>"+draftHtml;dialog.showModal();$("#modal-form").onsubmit=event=>event.preventDefault();
  $(`[data-doc-parse]`).onclick=async()=>{try{await api(base+"/parse",{method:"POST"});toast("解析完成");openDocumentWorkspace(resourceId)}catch(error){toast(error.message,true)}};$$(`[data-doc-fragment]`).forEach(input=>input.onchange=()=>{const derivativeId=input.dataset.docFragment,index=Number(input.dataset.index);let entry=state.agentDocumentContext.find(item=>item.resource_id===resourceId&&item.derivative_id===derivativeId);if(!entry){entry={resource_id:resourceId,derivative_id:derivativeId,item_indexes:[]};state.agentDocumentContext.push(entry)}if(input.checked&&!entry.item_indexes.includes(index))entry.item_indexes.push(index);if(!input.checked)entry.item_indexes=entry.item_indexes.filter(value=>value!==index);entry.item_indexes.sort((a,b)=>a-b);state.agentDocumentContext=state.agentDocumentContext.filter(item=>item.item_indexes.length);toast("文档片段选择已更新")});
  $(`[data-doc-create-draft]`).onclick=async()=>{try{if(!versions.length)return toast("请先解析并初始化文档版本",true);const modification=JSON.parse($(`[data-doc-modification]`).value),reason=$(`[data-doc-reason]`).value.trim();if(!reason)return toast("请输入修改原因",true);await api(base+"/change-drafts",{method:"POST",body:JSON.stringify({source_version_id:versions[versions.length-1].version_id,modification,reason})});toast("文档修改草案已创建");openDocumentWorkspace(resourceId)}catch(error){toast(error.message,true)}};$$(`[data-doc-approve]`).forEach(button=>button.onclick=async()=>{try{await api(base+"/change-drafts/"+encodeURIComponent(button.dataset.docApprove)+":decide",{method:"POST",body:JSON.stringify({approve:true,expected_version:Number(button.dataset.version)})});toast("已生成新文档版本");openDocumentWorkspace(resourceId)}catch(error){toast(error.message,true)}});$$(`[data-doc-reject]`).forEach(button=>button.onclick=async()=>{try{await api(base+"/change-drafts/"+encodeURIComponent(button.dataset.docReject)+":decide",{method:"POST",body:JSON.stringify({approve:false,expected_version:Number(button.dataset.version)})});toast("文档草案已拒绝");openDocumentWorkspace(resourceId)}catch(error){toast(error.message,true)}});
}

function fallbackLogout(){sessionStorage.clear();state.token=null;location.assign("/app/")}
async function sessionHandleUnauthorized(path,options){const method=options.method||"GET";const replay=async()=>{const attempt=await fetch(path,{...options,headers:{...options.headers,Accept:"application/json",Authorization:`Bearer ${state.token}`},cache:"no-store"});if(attempt.status===401)throw Error("登录已过期，请重新登录");if(!attempt.ok){let p={};try{p=await attempt.json()}catch{}throw Error(p.detail||p.title||`请求失败 (${attempt.status})`)}return attempt.status===204?null:attempt.json()};if(!state.sessionCoordinator)throw Error("登录已过期，请重新登录");return state.sessionCoordinator.onUnauthorized({method,idempotencyKey:options.headers?.["Idempotency-Key"]||null,replay})}
function sessionAttachAndRestore(){if(!state.sessionCoordinator)return;state.sessionCoordinator.attach(state.token,state.identity?.expires_at||null,state.config?.auth_mode||"oidc",state.config?.auth_mode==="oidc"?state.config:null);restoreRoute()}
async function restoreRoute(){const route=state.sessionCoordinator?state.sessionCoordinator.takeRoute():null;if(!route)return;if(route.view==="project-workspace"&&route.project_id&&window.CoifespWorkspace){await window.CoifespWorkspace.openProject(route.project_id);return}if(route.view==="team-project-detail"&&route.project_id){const project=state.teamProjects.find(p=>p.project_id===route.project_id);if(!project){toast("恢复的项目已不可用或当前账户无权访问",true);return}await openTeamProject(route.project_id);return}if(route.view==="agents"&&route.run_id){await openAgentWorkbench(route.run_id);return}if(route.view&&document.getElementById(`view-${route.view}`))show(route.view)}
async function loadConnectorsQuietly(){if(state.connectorsLoaded)return;state.connectorsLoaded=true;try{state.connectors=await api("/v1/connectors/available")}catch(e){state.connectors=[]}renderConnectorPanel()}
function renderConnectorPanel(){const panel=$("#connector-panel");if(!panel)return;const items=state.connectors||[];if(!items.length){panel.innerHTML=`<p class="muted">当前尚未配置外部连接器。团队管理员完成平台选择与凭据配置（OAuth Client、测试租户、最小 scope）后，这里才会展示真实可用的连接器与状态。</p>`;return}panel.innerHTML=items.map(c=>`<article class="card"><div class="card-head"><div><h4>${esc(c.connector_id)}</h4><div class="meta"><span class="pill ${c.status==="active"?"green":"orange"}">${esc(c.status)}</span><span>${esc(c.auth_type)}</span><span>v${c.version}</span></div></div></div></article>`).join("")||`<p class="muted">尚未配置外部连接器。</p>`}
window.CoifespOpenCodeWorkspace=openCodeWorkspace;
bootstrap();
